  "aty.cmp.method": "Kern = gleitendes 10. Perzentil des Schattendurchmessers (40-mm-Fenster), kein globales Mittel – Schlaufen drücken das Signal nur nach oben, die lokale untere Hüllkurve ist der echte Kern. Kern-CV = Schwankung dieses Kerns entlang des Garns. Frequenz / Abstand = Abstand der erkannten Schlaufenspitzen (Prominenz > 30 µm, min. Abstand 1 mm). Relative Höhe = Schlaufenhöhe in % des lokalen Kerns. Bulk-Index = gesamte Schlaufenfläche in % der Fläche eines schlaufenfreien Garns gleichen Kerns. Bin1/Bin2 = gleiche Höhen-/Längen-Aufteilung wie im Reiter Verteilung, auf diesen genaueren Schlaufen (die % weichen daher leicht ab). Kern-CV @1m / @20m = Ungleichmässigkeit des Kerns auf zwei Längenskalen. Ausreisser-Werte (P95/P99/max) = wie extrem die schlimmsten Schlaufen sind.",
