  "aty.cmp.method": "Núcleo = percentil 10 móvil del diámetro de sombra (ventana de 40 mm), no una media global – los bucles solo empujan la señal hacia arriba, así que la envolvente inferior local es el núcleo real. CV del núcleo = variación de ese núcleo a lo largo del hilo. Frecuencia / separación = distancia entre los picos de bucle detectados (prominencia > 30 µm, distancia mín. 1 mm). Altura relativa = altura del bucle en % del núcleo local. Índice de volumen = área total de bucles en % del área de un hilo sin bucles con el mismo núcleo. Bin1/Bin2 = misma división altura/longitud que la pestaña Distribución, sobre estos bucles más precisos (los % difieren un poco). CV del núcleo @1m / @20m = irregularidad del núcleo a dos escalas. Valores extremos (P95/P99/máx.) = cuán extremos son los peores bucles.",
